-- Live QA cohort query; adjust UTC bounds for later visits. Legacy commerce copies are excluded.
SELECT 'all' AS dimension, 'all' AS segment, variant, count() AS visitors, sum(u.engaged) AS engaged, sum(u.cta_clicks) AS cta_clicks, sum(u.carts) AS carts, sum(u.checkouts) AS checkouts, sum(u.purchases) AS purchases, sum(u.payment_errors) AS payment_errors, sum(u.revenue) AS revenue, count()-sum(u.engaged) AS bounce FROM (SELECT e.properties.experiment_unit_id AS unit_id, any(x.variant) AS variant, any(x.device) AS device, any(x.channel) AS channel, toInt(countIf(e.event='view_item')>0) AS engaged, toInt(countIf(e.event='product_cta_clicked')>0) AS cta_clicks, toInt(countIf(e.event='add_to_cart')>0) AS carts, toInt(countIf(e.event='begin_checkout')>0) AS checkouts, toInt(countIf(e.event='purchase')>0) AS purchases, toInt(countIf(e.event='payment_error')>0) AS payment_errors, sumIf(toFloat(e.properties.value),e.event='purchase') AS revenue FROM events AS e INNER JOIN (SELECT properties.experiment_unit_id AS unit_id, min(timestamp) AS exposed_at, argMin(properties.variant,timestamp) AS variant, argMin(properties.device,timestamp) AS device, argMin(properties.acquisition_channel,timestamp) AS channel FROM events WHERE timestamp >= '2026-11-22' AND timestamp < '2026-11-24' AND properties.dataset_id = 'fieldwork_experiment_live_v1' AND properties.experiment_id = 'fw_quick_add_v1' AND properties.data_source IN ('experiment_synthetic_seed','experiment_backend') AND (event NOT IN ('add_to_cart','remove_from_cart','begin_checkout','return_to_cart','add_payment_info','purchase','payment_error') OR properties.commerce_event_id IS NOT NULL) AND (event != 'view_item' OR properties.demo_user_id IS NULL OR properties.commerce_event_id IS NOT NULL) AND event = 'experiment_exposure' GROUP BY unit_id) AS x ON e.properties.experiment_unit_id=x.unit_id WHERE e.timestamp >= '2026-11-22' AND e.timestamp < '2026-11-24' AND e.properties.dataset_id = 'fieldwork_experiment_live_v1' AND e.properties.experiment_id = 'fw_quick_add_v1' AND e.properties.data_source IN ('experiment_synthetic_seed','experiment_backend') AND (event NOT IN ('add_to_cart','remove_from_cart','begin_checkout','return_to_cart','add_payment_info','purchase','payment_error') OR e.properties.commerce_event_id IS NOT NULL) AND (event != 'view_item' OR e.properties.demo_user_id IS NULL OR e.properties.commerce_event_id IS NOT NULL) AND e.timestamp>=x.exposed_at GROUP BY unit_id) AS u GROUP BY segment,variant ORDER BY segment,variant LIMIT 20
